window.kbPageData["views/entry/k-1b242ff768360f03"] = {"key":"entry/k-1b242ff768360f03","state":{"route":"entry/k-1b242ff768360f03"},"node":{"id":"k-1b242ff768360f03","mode":"k","title":"彩票式盲盒交易的效力与退款","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["未经许可的彩票类博弈交易所生债务的法律效力"],"qs":["江苏 2024 B类 行测#19"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"尚未核实与苏某案情对应的裁判原文，需核对法院对交易性质、合同效力、返还请求及购卡款处理的具体认定。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：苏某为获取博弈利益，无权要求返还购买卡片的款项","review":{"definition":"原题引文：苏某为获取博弈利益，无权要求返还购买卡片的款项","explanation":"本题选C。解析把卡片主要用作兑奖凭证、苏某为中大奖反复购卡和经营方未经许可合在一起，认定交易具有彩票式博弈性质。购卡款如何处理还要审查具体请求和适用依据。《民法典》第一百五十七条对民事法律行为无效后的财产返还已有一般规则，因此将债务认定为不受保护后，仍需查明该案拒绝返还的具体理由。","references":[{"source":"web-b8302bf465d32129","location":"第二条、第三条","quote":"未经国务院特许，禁止发行其他彩票"},{"source":"web-bc3f8ab1e5a22ac1","location":"第一百五十七条","quote":"行为人因该行为取得的财产，应当予以返还"}],"evidence":"苏某为获取博弈利益，无权要求返还购买卡片的款项","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 B类 行测#19":{"paper":"江苏 2024 B类 行测","n":19,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",3],"asrc":["8dd171daee6fc74e9718.pdf",7],"card":"927aa3877fd16060dea20c45","links":[{"id":"k-1b242ff768360f03","role":"直接考查","why":"解析将涉案卡片交易认定为类似购买彩票的行为，并据经营方未获许可判断购卡款返还请求的效力。"}]}},"terms":{},"references":{"web-b8302bf465d32129":{"name":"《彩票管理条例》","url":"https://xzfg.moj.gov.cn/front/law/detail?LawID=292"},"web-bc3f8ab1e5a22ac1":{"name":"《中华人民共和国民法典》","url":"https://nmca.miit.gov.cn/zwgk/zcwj/flfg/art/2021/art_fa4b2d35db784827b280bc785e8df7d5.html"}},"topics":[],"units":{"k-1b242ff768360f03":[["江苏 2024 B类 行测#19"]]}};
